css:
.cosmic-ripple {
  width: 100%;
  height: 100%;
  background: linear-gradient(
    135deg,
    rgba(50, 25, 10, 0.9) 0%,
    rgba(100, 25, 0, 0.066) 50%,
    rgba(20, 5, 0, 0.5) 100%
  );
  filter: url(#cosmic-texture);
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
}

.cosmic-ripple::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: rgba(0, 0, 0, 0.7);
  pointer-events: none;
}
